#!/usr/bin/env python3
"""Apply open Dependabot security alerts safely.

Strategy:
- Plain requirements.txt: bump pinned versions (supports extras).
- uv-compiled requirements.txt / uv.lock: queue `uv pip compile` + `uv lock`
  with --upgrade-package (never rewrite lock hashes by hand).
- package.json / package-lock.json: bump package.json ranges, queue `npm install`
  to regenerate the lock (never rewrite lock hashes by hand).

Reads alerts from GITHUB_ALERTS_JSON_FILE, GITHUB_ALERTS_JSON, or stdin.
"""

from __future__ import annotations

import json
import os
import re
import subprocess
import sys
from collections import defaultdict
from pathlib import Path

try:
    from packaging.version import InvalidVersion, Version
except ImportError:  # pragma: no cover - CI installs packaging
    Version = None  # type: ignore
    InvalidVersion = Exception  # type: ignore


ROOT = Path(os.environ.get("GITHUB_WORKSPACE", ".")).resolve()
SUMMARY_PATH = Path(os.environ.get("SECURITY_FIX_SUMMARY", "security-fix-summary.md"))
SKIP_REGEN = os.environ.get("SECURITY_FIX_SKIP_REGEN", "").lower() in {
    "1",
    "true",
    "yes",
}


def parse_version(value: str):
    if Version is None:
        return None
    try:
        return Version(value.lstrip("vV"))
    except InvalidVersion:
        return None


def needs_bump(current: str, target: str) -> bool:
    cur_v, tgt_v = parse_version(current), parse_version(target)
    if cur_v is not None and tgt_v is not None:
        return cur_v < tgt_v
    return current != target


def load_alerts() -> list[dict]:
    alerts_file = os.environ.get("GITHUB_ALERTS_JSON_FILE")
    raw = os.environ.get("GITHUB_ALERTS_JSON")
    if alerts_file:
        data = json.loads(Path(alerts_file).read_text(encoding="utf-8"))
    elif raw:
        data = json.loads(raw)
    else:
        data = json.load(sys.stdin)
    if not isinstance(data, list):
        raise SystemExit("Expected a JSON list of Dependabot alerts")
    return data


def collect_targets(alerts: list[dict]) -> dict[tuple[str, str], dict]:
    """Map (manifest_path, package) -> best patch target."""
    targets: dict[tuple[str, str], dict] = {}
    for alert in alerts:
        if alert.get("state") != "open":
            continue
        dep = alert.get("dependency") or {}
        pkg = (dep.get("package") or {}).get("name")
        manifest = dep.get("manifest_path")
        vuln = alert.get("security_vulnerability") or {}
        patched = (vuln.get("first_patched_version") or {}).get("identifier")
        if not pkg or not manifest or not patched:
            continue
        key = (manifest, pkg)
        severity = (alert.get("security_advisory") or {}).get("severity") or "unknown"
        existing = targets.get(key)
        if existing is None or needs_bump(existing["patched"], patched):
            targets[key] = {
                "package": pkg,
                "manifest": manifest,
                "patched": patched,
                "severity": severity,
                "alert_numbers": [alert.get("number")],
                "ecosystem": (dep.get("package") or {}).get("ecosystem"),
            }
        else:
            existing["alert_numbers"].append(alert.get("number"))
    return targets


REQ_EQ_RE = re.compile(
    r"^(?P<prefix>\s*)(?P<name>[A-Za-z0-9_.\-]+)"
    r"(?P<extras>\[[^\]]*\])?"
    r"(?P<op>==|===)(?P<ver>[^\s#;]+)"
    r"(?P<suffix>\s*(?:#.*)?)$",
    re.IGNORECASE,
)
REQ_PIN_RE = re.compile(
    r"^(?P<prefix>\s*)(?P<name>[A-Za-z0-9_.\-]+)"
    r"(?P<extras>\[[^\]]*\])?"
    r"(?P<op>>=|~=)(?P<ver>[^\s#;,]+)"
    r"(?P<rest>[^#]*)(?P<suffix>\s*(?:#.*)?)$",
    re.IGNORECASE,
)

UV_AUTOGEN_MARKERS = (
    "autogenerated by uv",
    "this file was autogenerated by uv",
    "uv pip compile",
)


def is_uv_compiled_requirements(path: Path) -> bool:
    if not path.is_file():
        return False
    head = path.read_text(encoding="utf-8", errors="ignore")[:400].lower()
    return any(marker in head for marker in UV_AUTOGEN_MARKERS)


def bump_requirements(path: Path, package: str, patched: str) -> bool:
    if not path.is_file():
        return False
    lines = path.read_text(encoding="utf-8").splitlines(keepends=True)
    changed = False
    out: list[str] = []
    for line in lines:
        if line.endswith("\r\n"):
            ending = "\r\n"
            stripped = line[:-2]
        elif line.endswith("\n"):
            ending = "\n"
            stripped = line[:-1]
        else:
            ending = ""
            stripped = line
        m = REQ_EQ_RE.match(stripped) or REQ_PIN_RE.match(stripped)
        if not m or m.group("name").lower() != package.lower():
            out.append(line)
            continue
        current = m.group("ver")
        if not needs_bump(current, patched):
            out.append(line)
            continue
        op = "==" if m.group("op") in ("==", "===") else m.group("op")
        extras = m.group("extras") or ""
        rest = m.groupdict().get("rest") or ""
        suffix = m.group("suffix") or ""
        out.append(
            f"{m.group('prefix')}{m.group('name')}{extras}{op}{patched}{rest}{suffix}{ending}"
        )
        changed = True
    if changed:
        path.write_text("".join(out), encoding="utf-8")
    return changed


PKG_JSON_DEP_KEYS = (
    "dependencies",
    "devDependencies",
    "optionalDependencies",
    "peerDependencies",
)


def bump_package_json(path: Path, package: str, patched: str) -> bool:
    if not path.is_file():
        return False
    data = json.loads(path.read_text(encoding="utf-8"))
    changed = False
    for key in PKG_JSON_DEP_KEYS:
        deps = data.get(key)
        if not isinstance(deps, dict) or package not in deps:
            continue
        current_spec = str(deps[package])
        m = re.match(r"^([\^~>=]*)(.+)$", current_spec.strip())
        if not m:
            continue
        prefix, current = m.group(1), m.group(2).lstrip("=")
        current = current.split()[0]
        if not needs_bump(current, patched) and current == patched:
            continue
        if current == patched and prefix not in ("", "=", "=="):
            # Already at patched with range prefix.
            continue
        if not needs_bump(current, patched) and current == patched:
            continue
        if not needs_bump(current, patched):
            continue
        if prefix in ("", "=", "=="):
            deps[package] = patched
        else:
            deps[package] = f"{prefix}{patched}"
        changed = True
    if changed:
        path.write_text(json.dumps(data, indent=2) + "\n", encoding="utf-8")
    return changed


def rel(path: Path) -> str:
    try:
        return str(path.resolve().relative_to(ROOT))
    except ValueError:
        return str(path)


def run_cmd(cmd: list[str], cwd: Path) -> bool:
    print(f"+ ({cwd}) {' '.join(cmd)}", flush=True)
    try:
        subprocess.run(cmd, cwd=cwd, check=True)
        return True
    except (subprocess.CalledProcessError, FileNotFoundError) as exc:
        print(f"! command failed: {exc}", flush=True)
        return False


def patched_constraint(package: str, patched: str) -> str:
    """Prefer the patched release without jumping past its major line."""
    ver = parse_version(patched)
    if ver is None:
        return f"{package}>={patched}"
    return f"{package}>={patched},<{ver.major + 1}"


def regenerate_uv(directory: Path, package_targets: dict[str, str]) -> set[str]:
    """Regenerate requirements.txt + uv.lock via uv for a consistent resolve."""
    changed: set[str] = set()
    if not package_targets:
        return changed
    pyproject = directory / "pyproject.toml"
    requirements = directory / "requirements.txt"
    lock = directory / "uv.lock"
    if not pyproject.is_file():
        print(f"! skip uv regen (no pyproject.toml): {directory}")
        return changed

    # Deduplicate case-insensitively, keep highest patched target.
    merged: dict[str, str] = {}
    for pkg, patched in package_targets.items():
        key = pkg.lower()
        if key not in merged or needs_bump(merged[key], patched):
            merged[key] = patched
    names = {pkg.lower(): pkg for pkg in package_targets}

    upgrade_flags: list[str] = []
    constraint_lines: list[str] = []
    for key in sorted(merged):
        pkg = names[key]
        patched = merged[key]
        upgrade_flags.extend(["--upgrade-package", pkg])
        constraint_lines.append(patched_constraint(pkg, patched))

    constraints = directory / ".security-auto-fix.constraints.txt"
    constraints.write_text("\n".join(constraint_lines) + "\n", encoding="utf-8")

    before_req = requirements.read_bytes() if requirements.is_file() else None
    before_lock = lock.read_bytes() if lock.is_file() else None

    compile_base = [
        "uv",
        "pip",
        "compile",
        "pyproject.toml",
        "-o",
        "requirements.txt",
    ]
    try:
        # Prefer same-major patched floors first; if that cannot resolve
        # (common when a transitive security floor forces a direct major bump),
        # fall back to unconstrained --upgrade-package so uv can move the set.
        ok = run_cmd(
            [*compile_base, "--constraint", constraints.name, *upgrade_flags],
            directory,
        )
        if not ok:
            print(
                f"! constrained uv resolve failed in {directory}; "
                "retrying without major caps",
                flush=True,
            )
            ok = run_cmd([*compile_base, *upgrade_flags], directory)
        if not ok:
            return changed

        if not run_cmd(
            ["uv", "lock", "--constraint", constraints.name, *upgrade_flags],
            directory,
        ):
            run_cmd(["uv", "lock", *upgrade_flags], directory)
    finally:
        if constraints.is_file():
            constraints.unlink()

    if requirements.is_file() and requirements.read_bytes() != before_req:
        changed.add(rel(requirements))
    if lock.is_file() and lock.read_bytes() != before_lock:
        changed.add(rel(lock))
    return changed


def regenerate_npm(directory: Path) -> set[str]:
    changed: set[str] = set()
    package_json = directory / "package.json"
    lock = directory / "package-lock.json"
    if not package_json.is_file():
        return changed
    before_json = package_json.read_bytes()
    before_lock = lock.read_bytes() if lock.is_file() else None
    if not run_cmd(
        ["npm", "install", "--package-lock-only", "--ignore-scripts"], directory
    ):
        # Fallback: full install still refreshes the lock.
        if not run_cmd(["npm", "install", "--ignore-scripts"], directory):
            return changed
    if package_json.read_bytes() != before_json:
        changed.add(rel(package_json))
    if lock.is_file() and lock.read_bytes() != before_lock:
        changed.add(rel(lock))
    return changed


def main() -> int:
    alerts = load_alerts()
    targets = collect_targets(alerts)
    changed_files: set[str] = set()
    applied: list[dict] = []
    skipped: list[dict] = []

    uv_upgrades: dict[Path, dict[str, str]] = defaultdict(dict)
    npm_dirs: set[Path] = set()

    for (_manifest, _pkg), info in sorted(
        targets.items(), key=lambda x: (x[0][0], x[0][1].lower())
    ):
        manifest = info["manifest"]
        package = info["package"]
        patched = info["patched"]
        path = ROOT / manifest
        name = path.name.lower()

        if name == "uv.lock":
            existing = uv_upgrades[path.parent].get(package)
            if existing is None or needs_bump(existing, patched):
                uv_upgrades[path.parent][package] = patched
            applied.append(info)
            continue

        if name == "requirements.txt":
            if is_uv_compiled_requirements(path):
                existing = uv_upgrades[path.parent].get(package)
                if existing is None or needs_bump(existing, patched):
                    uv_upgrades[path.parent][package] = patched
                applied.append(info)
                continue
            if bump_requirements(path, package, patched):
                changed_files.add(manifest)
                applied.append(info)
            else:
                skipped.append(info)
            continue

        if name == "package.json":
            if bump_package_json(path, package, patched):
                changed_files.add(manifest)
                npm_dirs.add(path.parent)
                applied.append(info)
            else:
                # Still regenerate lock if alert pointed at package.json but range
                # already includes patched (lock may be stale).
                npm_dirs.add(path.parent)
                skipped.append(info)
            continue

        if name == "package-lock.json":
            sibling = path.with_name("package.json")
            if sibling.is_file():
                bumped = bump_package_json(sibling, package, patched)
                if bumped:
                    changed_files.add(rel(sibling))
            npm_dirs.add(path.parent)
            applied.append(info)
            continue

        if info.get("ecosystem") == "pip" and path.suffix in {".txt", ".in"}:
            if bump_requirements(path, package, patched):
                changed_files.add(manifest)
                applied.append(info)
            else:
                skipped.append(info)
            continue

        skipped.append(info)

    regen_notes: list[str] = []
    if not SKIP_REGEN:
        for directory, package_targets in sorted(
            uv_upgrades.items(), key=lambda x: str(x[0])
        ):
            updated = regenerate_uv(directory, package_targets)
            changed_files.update(updated)
            pkgs = ", ".join(
                f"{name}>={ver}"
                for name, ver in sorted(
                    package_targets.items(), key=lambda i: i[0].lower()
                )
            )
            regen_notes.append(f"- uv regenerate `{rel(directory)}`: {pkgs}")
        for directory in sorted(npm_dirs, key=str):
            updated = regenerate_npm(directory)
            changed_files.update(updated)
            regen_notes.append(f"- npm regenerate `{rel(directory)}`")
    else:
        regen_notes.append("- regeneration skipped (SECURITY_FIX_SKIP_REGEN)")

    by_manifest: dict[str, list[dict]] = defaultdict(list)
    for item in applied:
        by_manifest[item["manifest"]].append(item)

    lines = [
        "## Security auto-fix summary",
        "",
        f"- Open alerts considered: **{len(alerts)}**",
        f"- Unique package/manifest targets: **{len(targets)}**",
        f"- Applied (queued or bumped): **{len(applied)}**",
        f"- Skipped: **{len(skipped)}**",
        "",
    ]
    if applied:
        lines.append("### Applied")
        lines.append("")
        for manifest, items in sorted(by_manifest.items()):
            lines.append(f"- `{manifest}`")
            for item in sorted(items, key=lambda i: i["package"].lower()):
                nums = ", ".join(f"#{n}" for n in item["alert_numbers"] if n)
                lines.append(
                    f"  - `{item['package']}` → `{item['patched']}` "
                    f"({item['severity']}; alerts {nums})"
                )
        lines.append("")
    if regen_notes:
        lines.append("### Lock / compile regeneration")
        lines.append("")
        lines.extend(regen_notes)
        lines.append("")
    if skipped:
        lines.append("### Skipped")
        lines.append("")
        for item in skipped[:50]:
            lines.append(
                f"- `{item['manifest']}` / `{item['package']}` → `{item['patched']}`"
            )
        if len(skipped) > 50:
            lines.append(f"- …and {len(skipped) - 50} more")
        lines.append("")

    lines.append("cc @gautammanak1 for review")
    lines.append("")

    SUMMARY_PATH.write_text("\n".join(lines), encoding="utf-8")
    changed_list = ROOT / "security-fix-changed.txt"
    changed_list.write_text(
        "\n".join(sorted(changed_files)) + ("\n" if changed_files else ""),
        encoding="utf-8",
    )
    print(f"Applied {len(applied)} targets; {len(changed_files)} files changed")
    for path in sorted(changed_files):
        print(f"CHANGED {path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
